// Success path: YouTube accepted the upload.
const row = $('Loop Over Rows').item.json;
const uploaded = $input.first().json;

// The YouTube node returns { uploadId }; older builds returned the raw resource.
const videoId = uploaded.uploadId || uploaded.id?.videoId || uploaded.id || '';
const url = videoId ? `https://www.youtube.com/watch?v=${videoId}` : '';

const requested = String(row.Platforms || '')
  .toLowerCase()
  .split(',')
  .map((p) => p.trim())
  .filter(Boolean);

const platformCols = {
  instagram: 'Instagram Status',
  facebook: 'Facebook Status',
  youtube: 'YouTube Status',
  linkedin: 'LinkedIn Status',
  pinterest: 'Pinterest Status',
  threads: 'Threads Status',
};

const statuses = {};
for (const [key, col] of Object.entries(platformCols)) {
  statuses[col] = key === 'youtube' ? (url ? `Posted: ${url}` : 'Posted') : row[col] || '';
}

// The row is only fully Posted once every platform it targets has succeeded;
// otherwise it stays Approved so the other publishers can still pick it up.
const allDone =
  requested.length > 0 &&
  requested.every((p) => String(statuses[platformCols[p]] || '').toLowerCase().startsWith('posted'));

return [
  {
    json: {
      'Content ID': row['Content ID'],
      Status: allDone ? 'Posted' : 'Approved',
      'Retry Count': row['Retry Count'] || 0,
      'Posted At': allDone ? new Date().toISOString() : row['Posted At'] || '',
      Error: '',
      ...statuses,
      _failed: false,
    },
  },
];

// Failure path: Drive download or YouTube upload threw.
const MAX_RETRIES = 3;
const row = $('Loop Over Rows').item.json;
const err = $input.first().json;

const reason =
  err?.error?.message ||
  err?.message ||
  err?.error ||
  'Upload failed (no error detail returned)';

const retryCount = Number(row['Retry Count'] || 0) + 1;
const giveUp = retryCount >= MAX_RETRIES;

// Back off further on each attempt so a transient Google outage isn't
// hammered every 5 minutes.
const nextAttempt = new Date(Date.now() + 15 * retryCount * 60000).toISOString();

const platformCols = {
  instagram: 'Instagram Status',
  facebook: 'Facebook Status',
  youtube: 'YouTube Status',
  linkedin: 'LinkedIn Status',
  pinterest: 'Pinterest Status',
  threads: 'Threads Status',
};

const statuses = {};
for (const [key, col] of Object.entries(platformCols)) {
  statuses[col] = key === 'youtube' ? `Failed: ${String(reason).slice(0, 180)}` : row[col] || '';
}

return [
  {
    json: {
      'Content ID': row['Content ID'],
      Status: giveUp ? 'Failed' : 'Retry Pending',
      'Retry Count': retryCount,
      'Posted At': row['Posted At'] || '',
      'Scheduled DateTime': giveUp ? row['Scheduled DateTime'] : nextAttempt,
      Error: `YouTube: ${String(reason).slice(0, 400)}`,
      ...statuses,
      _failed: true,
      _giveUp: giveUp,
    },
  },
];
